// Create a new mutable Yoga configuration and wrap it in a pool-managed handle (YGConfigRef*)
YGConfigRef raw = YGConfigNew();
if (!raw) { FUZZ_BAIL(); }
// Allocate a wrapper pointer so the fuzzer runtime can pool a YGConfigRef *
YGConfigRef *config = new YGConfigRef;
*config = raw;
// Track mutability and lifetime on the wrapper object
FUZZ_SET_ATTR_INT(config, "mutable", 1);
FUZZ_SET_ATTR_INT(config, "default", 0);
FUZZ_SET_ATTR_INT(config, "freed", 0);
// Initialize tracked state attributes to known defaults
FUZZ_SET_ATTR_INT(config, "useWebDefaults_set", 0);
FUZZ_SET_ATTR_INT(config, "psf_set", 0);
FUZZ_SET_ATTR_INT(config, "errata_set", 0);
FUZZ_SET_ATTR_INT(config, "logger_set", 0);
FUZZ_SET_ATTR_INT(config, "ctx_owned", 0);
FUZZ_SET_ATTR_INT(config, "exp_WebFlexBasis_set", 0);
FUZZ_SET_ATTR_INT(config, "cloner_set", 0);
// Validation: creation succeeded and object metadata initialized for downstream API usage.

// Enforce: config must be a valid, mutable configuration not yet freed and not the default
int is_mutable = FUZZ_GET_ATTR_INT(config, "mutable");
int is_default = FUZZ_GET_ATTR_INT(config, "default");
int is_freed = FUZZ_GET_ATTR_INT(config, "freed");
if (!is_mutable || is_default || is_freed) { FUZZ_BAIL(); }
// If we set a context we own, free it before destroying the config to avoid leaks
int ctx_owned = FUZZ_GET_ATTR_INT(config, "ctx_owned");
if (ctx_owned) {
  void* ctx = FUZZ_GET_ATTR_PTR(config, "ctx");
  if (ctx) { delete[] static_cast<char*>(ctx); }
  FUZZ_SET_ATTR_INT(config, "ctx_owned", 0);
  FUZZ_SET_ATTR_PTR(config, "ctx", nullptr);
}
// Destroy the configuration; after this, it must not be used
YGConfigFree(*config);
FUZZ_SET_ATTR_INT(config, "freed", 1);
// Validation: ensures correct lifetime semantics and avoids double-free by not returning the handle.

// Obtain the immutable default configuration and wrap it in a pool-managed handle
YGConfigConstRef def = YGConfigGetDefault();
if (!def) { FUZZ_BAIL(); }
YGConfigRef *config = new YGConfigRef;
*config = const_cast<YGConfigRef>(def);
// Track immutability and non-freeable status on the wrapper object
FUZZ_SET_ATTR_INT(config, "mutable", 0);
FUZZ_SET_ATTR_INT(config, "default", 1);
FUZZ_SET_ATTR_INT(config, "freed", 0);
// Validation: default config is marked immutable and must not be freed or mutated.

// Enforce mutability and alive state
int is_mutable = FUZZ_GET_ATTR_INT(config, "mutable");
int is_freed = FUZZ_GET_ATTR_INT(config, "freed");
if (!is_mutable || is_freed) { FUZZ_BAIL(); }
// Randomly choose enabled/disabled
bool enabled = (*FUZZ_PARAM(unsigned int) & 1u) != 0u;
YGConfigSetUseWebDefaults(*config, enabled);
// Track state for validation by getter
FUZZ_SET_ATTR_INT(config, "useWebDefaults", enabled ? 1 : 0);
FUZZ_SET_ATTR_INT(config, "useWebDefaults_set", 1);
// Validation: only mutable, live configs are mutated; state recorded for property checks.

// Getter can operate on mutable or immutable config; just ensure not freed
int is_freed = FUZZ_GET_ATTR_INT(config, "freed");
if (is_freed) { FUZZ_BAIL(); }
bool v = YGConfigGetUseWebDefaults(*config);
// If we previously set a value, it should match
int set_flag = FUZZ_GET_ATTR_INT(config, "useWebDefaults_set");
if (set_flag) {
  int expected = FUZZ_GET_ATTR_INT(config, "useWebDefaults");
  FUZZ_ASSERT(((v ? 1 : 0) == expected), "UseWebDefaults getter mismatch with prior set value");
}
// Validation: respects lifetime and asserts getter consistency when prior set exists.

// Enforce mutability and alive state
int is_mutable = FUZZ_GET_ATTR_INT(config, "mutable");
int is_freed = FUZZ_GET_ATTR_INT(config, "freed");
