  int got_milli = (int)(got * 1000.0f);
  int diff = got_milli - expected_milli;
  if (diff < 0) diff = -diff;
  FUZZ_ASSERT(diff <= 1, "PointScaleFactor getter mismatch with prior set value");
}
// Validation: avoids UAF and checks consistency with previously set value within tolerance.

