// Build a bitmask by OR-ing a random subset of known flags
YGErrata mask = (YGErrata)0;
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) { mask = (YGErrata)(mask | YGErrataStretchFlexBasis); }
if ((*FUZZ_PARAM(unsigned int) & 2u) != 0u) { mask = (YGErrata)(mask | YGErrataAbsolutePositionWithoutInsetsExcludesPadding); }
