if (is_freed) { FUZZ_BAIL(); }
YGErrata got = YGConfigGetErrata(*config);
int set_flag = FUZZ_GET_ATTR_INT(config, "errata_set");
if (set_flag) {
  int expected = FUZZ_GET_ATTR_INT(config, "errata_val");
  FUZZ_ASSERT(((int)got == expected), "Errata getter mismatch with prior set value");
}
// Validation: respects lifetime and checks property when prior mask was set.

// Enforce mutability and alive state
int is_mutable = FUZZ_GET_ATTR_INT(config, "mutable");
int is_freed = FUZZ_GET_ATTR_INT(config, "freed");
if (!is_mutable || is_freed) { FUZZ_BAIL(); }
// Install a capturing-less lambda compatible with YGLogger signature
YGLogger logger = [](YGConfigConstRef, YGNodeConstRef, YGLogLevel, const char* format, va_list args) -> int {
  (void)format; (void)args; return 0; // minimal, safe implementation
};
