int is_mutable = FUZZ_GET_ATTR_INT(config, "mutable");
int is_freed = FUZZ_GET_ATTR_INT(config, "freed");
if (!is_mutable || is_freed) { FUZZ_BAIL(); }
// Create a small owned buffer and copy fuzz data to ensure lifetime beyond this call
std::string s = FUZZ_PARAM_STR();
size_t len = s.size();
if (len > 64) { len = 64; }
char* buf = new char[len + 1];
for (size_t i = 0; i < len; ++i) { buf[i] = s[i]; }
