// Use known feature enum; toggle randomly
YGExperimentalFeature feature = YGExperimentalFeatureWebFlexBasis;
bool enabled = (*FUZZ_PARAM(unsigned int) & 1u) != 0u;
YGConfigSetExperimentalFeatureEnabled(*config, feature, enabled);
FUZZ_SET_ATTR_INT(config, "exp_WebFlexBasis", enabled ? 1 : 0);
FUZZ_SET_ATTR_INT(config, "exp_WebFlexBasis_set", 1);
