int set_flag = FUZZ_GET_ATTR_INT(config, "exp_WebFlexBasis_set");
if (set_flag) {
  int expected = FUZZ_GET_ATTR_INT(config, "exp_WebFlexBasis");
  FUZZ_ASSERT(((got ? 1 : 0) == expected), "ExperimentalFeature getter mismatch with prior set value");
}
// Validation: honors lifetime and checks consistency with prior setter when available.

// Enforce mutability and alive state
int is_mutable = FUZZ_GET_ATTR_INT(config, "mutable");
int is_freed = FUZZ_GET_ATTR_INT(config, "freed");
if (!is_mutable || is_freed) { FUZZ_BAIL(); }
// Provide a minimal, safe cloner; returning nullptr keeps the harness simple
