FUZZ_SET_ATTR_INT(config, "cloner_set", 1);
FUZZ_SET_ATTR_PTR(config, "cloner_ptr", (void*)cloner);
// Validation: installs a valid callback only on live mutable configs.

// Generate a random float value; occasionally force a NaN to cover the undefined path
float value = *FUZZ_PARAM(float);
if ((*FUZZ_PARAM(unsigned int) % 4u) == 0u) {
  // Create a NaN without headers; IEEE-754 float division by zero yields NaN
  float zero = 0.0f;
  value = zero / zero;
}

// Call the target function
bool is_undef = YGFloatIsUndefined(value);

// Validate: YGFloatIsUndefined must match NaN semantics (value != value iff NaN)
bool is_nan_by_cmp = (value != value);
FUZZ_ASSERT(is_undef == is_nan_by_cmp, "YGFloatIsUndefined must return true iff value is NaN");

// Validation summary: Exercises both NaN and non-NaN paths; asserts result matches IEEE isnan semantics.

// Build two YGValue instances with randomized units/values
YGValue lhs; YGValue rhs;

// Randomize units from the valid YGUnit domain [0..6]
unsigned int u_pick = *FUZZ_PARAM(unsigned int);
unsigned int v_pick = *FUZZ_PARAM(unsigned int);
YGUnit units[7] = {YGUnitUndefined, YGUnitPoint, YGUnitPercent, YGUnitAuto, YGUnitMaxContent, YGUnitFitContent, YGUnitStretch};
lhs.unit = units[u_pick % 7u];
rhs.unit = units[v_pick % 7u];

// Randomize numeric values; occasionally force equality for Point/Percent branch coverage
lhs.value = *FUZZ_PARAM(float);
rhs.value = *FUZZ_PARAM(float);
if ((lhs.unit == YGUnitPoint || lhs.unit == YGUnitPercent) && lhs.unit == rhs.unit) {
  if ((*FUZZ_PARAM(unsigned int) % 2u) == 0u) {
    rhs.value = lhs.value; // exact match path
  }
} else {
  // For non-Point/Percent or differing units, values are ignored for equality, but keep randomized
}

// Invoke the target operator
bool eq = (lhs == rhs);

// Manually compute the expected result per spec
bool same_unit = (lhs.unit == rhs.unit);
bool unit_ignores_value = (lhs.unit == YGUnitUndefined || lhs.unit == YGUnitAuto || lhs.unit == YGUnitFitContent || lhs.unit == YGUnitMaxContent || lhs.unit == YGUnitStretch);
bool expected = false;
if (same_unit) {
  if (unit_ignores_value) {
    expected = true; // equal regardless of numeric value
  } else {
    // Point or Percent require exact float equality
    expected = (lhs.value == rhs.value);
  }
} else {
  expected = false; // differing units are unequal
}

FUZZ_ASSERT(eq == expected, "operator== must follow YGValue unit/value equality rules");

// Validation summary: Covers same/different unit branches and both equal/unequal numeric cases for Point/Percent.

// Build two YGValue instances similar to operator== to exercise inequality logic
YGValue lhs; YGValue rhs;

// Randomize units in [0..6]
