unsigned int v_pick = *FUZZ_PARAM(unsigned int);
YGUnit units[7] = {YGUnitUndefined, YGUnitPoint, YGUnitPercent, YGUnitAuto, YGUnitMaxContent, YGUnitFitContent, YGUnitStretch};
lhs.unit = units[u_pick % 7u];
rhs.unit = units[v_pick % 7u];

// Randomize numeric values; sometimes enforce equality for Point/Percent
lhs.value = *FUZZ_PARAM(float);
rhs.value = *FUZZ_PARAM(float);
if ((lhs.unit == YGUnitPoint || lhs.unit == YGUnitPercent) && lhs.unit == rhs.unit) {
