    rhs.value = lhs.value; // ensures equality for these units
  }
}

// Invoke the target operator
bool ne = (lhs != rhs);

// Compute expected as the logical negation of the == semantics (without calling operator==)
bool same_unit = (lhs.unit == rhs.unit);
bool unit_ignores_value = (lhs.unit == YGUnitUndefined || lhs.unit == YGUnitAuto || lhs.unit == YGUnitFitContent || lhs.unit == YGUnitMaxContent || lhs.unit == YGUnitStretch);
bool eq_expected = false;
if (same_unit) {
  if (unit_ignores_value) {
    eq_expected = true; // equal regardless of numeric value
  } else {
    eq_expected = (lhs.value == rhs.value); // exact float equality for Point/Percent
  }
} else {
  eq_expected = false; // differing units are unequal
}
bool ne_expected = !eq_expected;

FUZZ_ASSERT(ne == ne_expected, "operator!= must be the logical negation of operator== for YGValue");

// Validation summary: Validates that operator!= mirrors the negation of == across unit/value combinations.

// Construct a YGValue and apply unary negation
YGValue in;
unsigned int u_pick = *FUZZ_PARAM(unsigned int);
YGUnit units[7] = {YGUnitUndefined, YGUnitPoint, YGUnitPercent, YGUnitAuto, YGUnitMaxContent, YGUnitFitContent, YGUnitStretch};
in.unit = units[u_pick % 7u];
