YGValue out = -in;

// Validate: unit preserved; numeric value negated exactly
FUZZ_ASSERT(out.unit == in.unit, "operator- must preserve unit");
FUZZ_ASSERT(out.value == -in.value, "operator- must negate numeric value exactly");

// Validation summary: Ensures unit invariance and exact numeric negation, including units where numeric value is semantically ignored.

